#include <windows.h>
#include <stdio.h>
typedef LONG (NTAPI *wait_fn)(ULONG,HANDLE*,ULONG,BOOLEAN,PLARGE_INTEGER);
int main(void) {
 wait_fn wait=(wait_fn)GetProcAddress(GetModuleHandleW(L"ntdll.dll"),"NtWaitForMultipleObjects");
 HANDLE input=CreateEventW(NULL,TRUE,TRUE,NULL), suspend=CreateEventW(NULL,FALSE,TRUE,NULL), events[2];
 LARGE_INTEGER zero; LONG status; unsigned i;zero.QuadPart=0;
 if(!wait||!input||!suspend)return 2;
 events[0]=input;events[1]=suspend;
 for(i=0;i<1000;++i)if(wait(2,events,1,TRUE,&zero)!=0)return 3;
 if(WaitForSingleObject(suspend,0)!=WAIT_OBJECT_0)return 4;
 printf("original input-first: 1000 ready-input iterations leave suspend unconsumed\n");
 SetEvent(suspend);events[0]=suspend;events[1]=input;
 status=wait(2,events,1,TRUE,&zero);if(status!=0)return 5;
 if(WaitForSingleObject(suspend,0)!=WAIT_TIMEOUT)return 6;
 if(wait(2,events,1,TRUE,&zero)!=1)return 7;
 printf("suspend-first: suspension consumed first, input selected next; PASS\n");
 CloseHandle(input);CloseHandle(suspend);return 0;
}
